# -*- coding: utf-8 -*-
"""Shared test fixtures: build a throw-away sample archive per session."""

from __future__ import annotations

import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from pitr.core import parse_lsn  # noqa: E402
from pitr.store import Catalog  # noqa: E402


@pytest.fixture(scope="session")
def sample_dir(tmp_path_factory) -> Path:
    """Deterministic sample archive generated by tools/make_sample.py."""
    out = tmp_path_factory.mktemp("sample") / "data"
    subprocess.run(
        [sys.executable, "-I", str(ROOT / "tools" / "make_sample.py"),
         "--out", str(out)],
        check=True, capture_output=True,
    )
    return out


@pytest.fixture()
def catalog(sample_dir) -> Catalog:
    return Catalog.load(sample_dir)


@pytest.fixture()
def packages_dir(tmp_path) -> Path:
    return tmp_path / "packages"


@pytest.fixture()
def app(sample_dir, packages_dir, monkeypatch):
    monkeypatch.setenv("PITR_DATA_DIR", str(sample_dir))
    monkeypatch.setenv("PITR_PACKAGES_DIR", str(packages_dir))
    monkeypatch.setenv("PITR_ALLOW_DEV_SECRET", "1")
    from pitr.webapp import create_app

    application = create_app()
    application.config.update(TESTING=True)
    return application


@pytest.fixture()
def client(app):
    return app.test_client()


def lsn(text: str) -> int:
    return parse_lsn(text)
